// spec: specs/ssr-infra.md (1.1) · кейс: .qa/tests/ssr-infra/SSR-INFRA-01.md
// seed: tests/seed.spec.ts (гость) · прод: только GET через API request, без браузера и JS.
import { test, expect } from '@playwright/test';
import { publicPaths, robotsMeta, rootTail, stripTags } from './ssr-infra.helpers';

test.describe('SSR/SSG — сырой HTML', () => {
  test('Публичные страницы: непустой [data-seo-body] с h1 в #root и robots «index, follow» #be4863 @desktop @prod-safe', async ({ request }) => {
    const paths = await publicPaths(request);
    for (const path of paths) {
      await test.step(path, async () => {
        const res = await request.get(path);
        expect(res.status(), `${path}: статус`).toBe(200);
        expect(res.headers()['content-type'], `${path}: content-type`).toContain('text/html');
        expect(res.headers()['x-robots-tag'] ?? '', `${path}: X-Robots-Tag без noindex`).not.toMatch(/noindex/i);
        const html = await res.text();

        expect(robotsMeta(html), `${path}: meta robots`).toEqual(['index, follow']);

        const root = rootTail(html);
        expect(root, `${path}: есть #root`).not.toBeNull();
        const block = root!.match(/<div\b[^>]*\bdata-seo-body\b[^>]*>([\s\S]*)/i)?.[1];
        expect(block, `${path}: [data-seo-body] внутри #root`).toBeTruthy();
        expect(stripTags(block!).length, `${path}: текст SEO-блока не пустой`).toBeGreaterThan(50);
        const h1 = block!.match(/<h1\b[^>]*>([\s\S]*?)<\/h1>/i)?.[1];
        expect(h1, `${path}: <h1> в SEO-блоке`).toBeTruthy();
        expect(stripTags(h1!), `${path}: текст h1`).not.toBe('');
      });
    }
  });
});
